'aria-label\', \'Go to slide \' + (i + 1));\n      (function (idx) {\n        bullet.addEventListener(\'click\', function () {\n          goToSlide(idx);\n          resetAutoplay();\n        });\n      })(i);\n      paginationEl.appendChild(bullet);\n    }\n  }\n\n  function goToSlide(idx) {\n    if (!totalSlides) return;\n    currentSlide = ((idx % totalSlides) + totalSlides) % totalSlides;\n    if (mainWrapper) {\n      mainWrapper.style.transform = \'translate3d(-\' + (currentSlide * 100) + \'%, 0, 0)\';\n    }\n    var nextIdx = (currentSlide + 1) % totalSlides;\n    secondSlides.forEach(function (sl, i) {\n      sl.classList.toggle(\'is-active\', i === currentSlide);\n      sl.classList.toggle(\'is-next\', i === nextIdx);\n    });\n    if (paginationEl) {\n      Array.from(paginationEl.children).forEach(function (b, i) {\n        b.classList.toggle(\'swiper-pagination-bullet-active\', i === currentSlide);\n      });\n    }\n  }\n\n  function resetAutoplay() {\n    if (autoplayTimer) clearInterval(autoplayTimer);\n    if (!reduceMotion && totalSlides > 1) {\n      autoplayTimer = setInterval(function () {\n        goToSlide(currentSlide + 1);\n      }, 2800);\n    }\n  }\n\n  if (totalSlides > 0) {\n    goToSlide(0);\n    resetAutoplay();\n\n    // Pointer swipe support on hero slider\n    var startX = null;\n    var heroBlock = document.querySelector(\'.hero-slider-block\');\n    if (heroBlock) {\n      heroBlock.addEventListener(\'pointerdown\', function (e) {\n        startX = e.clientX;\n      });\n      window.addEventListener(\'pointerup\', function (e) {\n        if (startX === null) return;\n        var dx = e.clientX - startX;\n        startX = null;\n        if (Math.abs(dx) > 36) {\n          goToSlide(currentSlide + (dx < 0 ? 1 : -1));\n          resetAutoplay();\n        }\n      });\n    }\n  }\n\n  // 2. FEATURES TABS ("Hirer" / "Talent")\n  var tabLinks = Array.from(document.querySelectorAll(\'.features-tabs .w-tab-link\'));\n  var tabPanes = Array.from(document.querySelectorAll(\'.features-tabs .w-tab-pane\'));\n  tabLinks.forEach(function (link) {\n    link.addEventListener(\'click\', function (e) {\n      e.preventDefault();\n      var targetTab = link.getAttribute(\'data-w-tab\');\n      tabLinks.forEach(function (l) {\n        l.classList.toggle(\'w--current\', l === link);\n      });\n      tabPanes.forEach(function (pane) {\n        var match = pane.getAttribute(\'data-w-tab\') === targetTab;\n        pane.classList.toggle(\'w--tab-active\', match);\n      });\n    });\n  });\n\n  // 3. CUSTOM RADIO BUTTONS IN USERNAME FORM\n  var radioLabels = Array.from(document.querySelectorAll(\'.radio-button-field\'));\n  radioLabels.forEach(function (label) {\n    var input = label.querySelector(\'input[type="radio"]\');\n    var visual = label.querySelector(\'.w-form-formradioinput\');\n    if (!input || !visual) return;\n    input.addEventListener(\'change\', function () {\n      var groupName = input.getAttribute(\'name\');\n      document.querySelectorAll(\'input[type="radio"][name="\' + groupName + \'"]\').forEach(function (r) {\n        var parentVis = r.closest(\'.radio-button-field\');\n        var v = parentVis ? parentVis.querySelector(\'.w-form-formradioinput\') : null;\n        if (v) v.classList.toggle(\'w--redirected-checked\', r.checked);\n      });\n    });\n    label.addEventListener(\'click\', function () {\n      input.checked = true;\n      input.dispatchEvent(new Event(\'change\'));\n    });\n  });\n\n  // 4. USERNAME 16-CHAR LIMIT & HINT COLOR\n  var usernameInput = document.getElementById(\'USERNAME\');\n  if (usernameInput) {\n    var hintEl = usernameInput.parentElement ? usernameInput.parentElement.querySelector(\'.form-text-12\') : null;\n    var MAX_LEN = 16;\n    usernameInput.setAttribute(\'maxlength\', String(MAX_LEN));\n    usernameInput.addEventListener(\'input\', function () {\n      if (usernameInput.value.length > MAX_LEN) {\n        usernameInput.value = usernameInput.value.slice(0, MAX_LEN);\n      }\n      if (hintEl) {\n        hintEl.style.color = usernameInput.value.length >= MAX_LEN ? \'#ff3b30\' : \'\';\n      }\n    });\n  }\n\n  // 5. CUSTOM FORM SUBMIT BUTTONS ([ms-code-submit-new] -> [ms-code-submit-old]) & WAITLIST SUCCESS STATE\n  document.querySelectorAll(\'[ms-code-submit-new]\').forEach(function (btn) {\n    btn.addEventListener(\'click\', function (e) {\n      e.preventDefault();\n      var submitId = btn.getAttribute(\'ms-code-submit-new\');\n      var oldBtn = document.querySelector(\'[ms-code-submit-old="\' + submitId + \'"]\');\n      if (oldBtn) oldBtn.click();\n    });\n  });\n\n  document.querySelectorAll(\'form\').forEach(function (form) {\n    form.addEventListener(\'submit\', function (e) {\n      e.preventDefault();\n      var wrapper = form.closest(\'.w-form\');\n      form.style.display = \'none\';\n      if (wrapper) {\n        var done = wrapper.querySelector(\'.w-form-done\');\n        if (done) done.style.display = \'block\';\n      }\n    });\n  });\n\n  // 6. FAQ ACCORDION (.faq-dd)\n  var faqItems = Array.from(document.querySelectorAll(\'.faq-dd\'));\n  faqItems.forEach(function (dd, idx) {\n    var toggle = dd.querySelector(\'.faq-dd-toggle\');\n    var list = dd.querySelector(\'.faq-dd-list\');\n    if (idx === 0) {\n      dd.classList.add(\'is-open\');\n      if (toggle) toggle.classList.add(\'w--open\');\n      if (list) list.classList.add(\'w--open\');\n    }\n    if (toggle) {\n      toggle.addEventListener(\'click\', function () {\n        var wasOpen = dd.classList.contains(\'is-open\');\n        faqItems.forEach(function (other) {\n          other.classList.remove(\'is-open\');\n          var t = other.querySelector(\'.faq-dd-toggle\');\n          var l = other.querySelector(\'.faq-dd-list\');\n          if (t) t.classList.remove(\'w--open\');\n          if (l) l.classList.remove(\'w--open\');\n        });\n        if (!wasOpen) {\n          dd.classList.add(\'is-open\');\n          toggle.classList.add(\'w--open\');\n          if (list) list.classList.add(\'w--open\');\n        }\n      });\n    }\n  });\n\n  // 7. MOBILE NAVBAR DRAWER (.w-nav-button / .w-nav-menu)\n  var navBtn = document.querySelector(\'.w-nav-button\');\n  var navMenu = document.querySelector(\'.w-nav-menu\');\n  if (navBtn && navMenu) {\n    navBtn.addEventListener(\'click\', function () {\n      var isOpen = navBtn.classList.toggle(\'w--open\');\n      if (isOpen) {\n        navMenu.setAttribute(\'data-nav-menu-open\', \'\');\n        navMenu.style.display = \'block\';\n      } else {\n        navMenu.removeAttribute(\'data-nav-menu-open\');\n        navMenu.style.display = \'\';\n      }\n    });\n    navMenu.querySelectorAll(\'a\').forEach(function (a) {\n      a.addEventListener(\'click\', function () {\n        if (window.innerWidth <= 991 && navBtn.classList.contains(\'w--open\')) {\n          navBtn.classList.remove(\'w--open\');\n          navMenu.removeAttribute(\'data-nav-menu-open\');\n          navMenu.style.display = \'\';\n        }\n      });\n    });\n  }\n\n  // 8. SCROLL REVEAL OBSERVER\n  var reveals = Array.from(document.querySelectorAll(\'.iso-reveal\'));\n  if (\'IntersectionObserver\' in window && !reduceMotion) {\n    reveals.forEach(function (el) { el.classList.remove(\'is-in\'); });\n    var io = new IntersectionObserver(function (entries) {\n      entries.forEach(function (en) {\n        if (en.isIntersecting) {\n          en.target.classList.add(\'is-in\');\n          io.unobserve(en.target);\n        }\n      });\n    }, { threshold: 0.12 });\n    reveals.forEach(function (el) { io.observe(el); });\n  } else {\n    reveals.forEach(function (el) { el.classList.add(\'is-in\'); });\n  }\n})();\n\n</script>\n</body>\n</html>';
